#!/bin/sh\n# countdown.sh – prints time remaining until END_DATE\n# If CURRENT_DATE env var is set, it is used as the reference "now" (useful for testing)\n\nif [ -z "$END_DATE" ]; then\n  echo "Error: END_DATE environment variable not set."\n  exit 1\nfi\n\nNOW="${CURRENT_DATE:-$(date -u +%Y-%m-%d)}"\n\n# Convert dates to epoch seconds\nEND_EPOCH=$(date -d "$END_DATE" +%s 2>/dev/null) || { echo "Error: Invalid END_DATE format."; exit 1; }\nNOW_EPOCH=$(date -d "$NOW" +%s 2>/dev/null) || { echo "Error: Invalid CURRENT_DATE format."; exit 1; }\n\nDIFF=$(( END_EPOCH - NOW_EPOCH ))\nif [ $DIFF -lt 0 ]; then\n  echo "The apocalypse has already arrived."\n  exit 0\nfi\n\nDAYS=$(( DIFF / 86400 ))\nHOURS=$(( (DIFF % 86400) / 3600 ))\nMINUTES=$(( (DIFF % 3600) / 60 ))\n\nprintf "⏳ Time until apocalypse: %d days, %02d hours, %02d minutes\n" "$DAYS" "$HOURS" "$MINUTES"\n
